    max-width: 400px;
}

.board-container {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 0.75rem;
    min-width: 250px;
    display: flex;
    flex-direction: column;
}

.column-header h4 {
    margin: 0 0 0.5rem 0;
    font-size: 1rem;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-assignee {
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #fff;
}

.priority-high {
    background-color: #dc3545;
}

.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-low {
    background-color: #198754;
}

.task-due {
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.25rem;
}

.column-footer {
    margin-top: 0.75rem;
}

.add-task-form {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.form-buttons {
    display: flex;
    gap: 0.5rem;
}

